const ring = (cx, cy, cz, rx, rz) => [0, 1, 2, 3, 4, 5, 6, 7].map((i) => [cx + rx * Math.cos((i * Math.PI) / 4), cy, cz + rz * Math.sin((i * Math.PI) / 4)]);
